// The Ys Origin apworld's location / item table in CleriaCore terms: res/ap/ys_origin.json,
// generated by tools/ap_import.py from YsOrigin-Archipelago/ys_origin (never hand-edited).
// The mapping and what each field means for the game glue: build/shell_re/ARCHIPELAGO.md §5-6.
#pragma once
#include <cstdint>
#include <map>
#include <optional>
#include <string>
#include <unordered_map>
#include <vector>

#include "cleria/json.hpp"

namespace cleria::ap::ys {

enum class Detect : std::uint8_t {
    Flag,      // g_flags[flag] >= 1                      (chests: the box flag; events; statues)
    ItemArr,   // XsoVm::item_arr[index] >= 1               ("Divine Blessing: Strengthen <gear>")
    Scene,     // entering scene `scene` (g_flags[505] changes to it)
    Bit,       // (g_flags[flag] >> bit) & 1                 (blessings: flag 217 = 0xD9)
    Floor,     // tower floor `floor` reached (via slot_data scene_floors[current scene])
    Unmapped,
};

struct VanillaItem {
    int item = 0;              // the INVINFO / g_flags item index (>= 0x200: AP-synthetic)
    std::string name, cls;
};

struct Location {
    std::int64_t id = 0;
    std::string name, key, type, zone, floor, room;
    int scene = 0;             // the room (S_xxxx leaf number) or 0
    bool excluded = false;     // the apworld keeps these filler-only
    Detect detect = Detect::Unmapped;
    int flag = -1, index = -1, bit = -1, detect_scene = 0, detect_floor = 0;
    int statue_scene = 0;      // statues: scene-detected instead when statue_warp_locks is on
    int box_flag = -1;         // chests: the box flag (-1 none / not a chest)
    std::string script;        // chests: the action script ("MAP/S_10/S_1001/S_BOX01.XSO")
    std::vector<std::string> chars;   // empty = every character
    std::vector<VanillaItem> vanilla;
};

enum class ItemKind : std::uint8_t {
    Item,                 // a plain inventory item: g_flags[flag]
    Sp,                   // SP currency + amount
    Trap,                 // by name: EXP Leech, Chaos Warp, Butterfingers, Blinding Fog
    StatueUnlock,         // statue_warp_locks: unlocks the statue of `scene` (purify flag `flag`)
    ProgressiveGear,      // Progressive Armor / Boots: the next unowned tier of the character's ladder
    ProgressiveSkill,     // Wind / Lightning / Fire: artifact + power, then level_cell + 1 (max 3)
    ProgressiveBlessing,  // the next unset bit of `bits` in g_flags[217]
    CleriaOre,            // the weapon tier (not the item cell)
    Gem,                  // Emerald / Ruby / Topaz: level_cell + 1 (max 3)
    Blessing,             // a blessing effect: bit `bit` of g_flags[217]
    Unknown,
};

struct Item {
    std::int64_t id = 0;
    std::string name, cls;     // cls: filler / useful / progression / trap (the apworld default)
    ItemKind kind = ItemKind::Unknown;
    int flag = -1;             // Item / CleriaOre / StatueUnlock: the g_flags index
    int companion_flag = -1;   // Item: a power / bracelet cell granted with it (skill_grants)
    int amount = 0;            // Sp
    int scene = 0;             // StatueUnlock: the statue's scene
    int bit = -1;              // Blessing: the bit of g_flags[217]
    std::vector<int> bits;     // ProgressiveBlessing: bits in grant order
    int index = -1, level_cell = -1;          // Gem: synthetic index (0x300..), its level cell
    int artifact = -1, power = -1;            // ProgressiveSkill (+ level_cell)
    std::map<std::string, std::vector<int>> ladder;   // ProgressiveGear: character -> g_flags tiers
    std::vector<std::string> chars;
    bool goal_item = false;
};

struct Table {
    std::int64_t location_base = 0, item_base = 0;
    std::string commit;                               // the apworld commit it was made from
    std::vector<Location> locations;                  // by id
    std::vector<Item> items;                          // by id
    std::map<int, std::string> scene_names;
    std::map<int, int> scene_floors;

    const Location* location(std::int64_t id) const;
    const Item* item(std::int64_t id) const;
    const Location* chest_by_script(const std::string& script) const;   // case-insensitive, '/' or '\'
    std::vector<const Location*> by_flag(int flag) const;               // Detect::Flag locations of a cell

    std::unordered_map<std::int64_t, std::size_t> loc_index_, item_index_;
};

// Loads res/ap/ys_origin.json (the document form, for tests: from_json).
std::optional<Table> load(const std::string& path, std::string* err = nullptr);
std::optional<Table> from_json(const json::Value& doc, std::string* err = nullptr);

}  // namespace cleria::ap::ys
